<script>document.getElementById('add-item').addEventListener('click',()=>{const root=document.getElementById('order-items');if(root.children.length>=20)return;const row=document.getElementById('item-row-template').content.firstElementChild.cloneNode(true);const i=root.children.length;row.querySelector('select').name=`items[${i}][service_id]`;row.querySelector('input').name=`items[${i}][quantity]`;row.querySelector('.remove-item').addEventListener('click',()=>{row.remove();[...root.children].forEach((el,n)=>{el.querySelector('select').name=`items[${n}][service_id]`;el.querySelector('input').name=`items[${n}][quantity]`})});root.append(row)});</script>
